  await expect(page.locator(".manual-inheritance")).toBeVisible();
  await page.screenshot({ path: `${directory}/house-guide.png` });
  await hold();
  await page.locator('.manual-desktop-contents a[href="#flow"]').click();
  await expect(page.getByRole("heading", { name: "Writing in flow", exact: true })).toBeVisible();
  await hold();
  await page.locator('.manual-desktop-contents a[href="#shortcuts"]').click();
  await expect(page.getByRole("radio", { name: "macOS" })).toBeChecked();
  await expect(page.locator(".manual-shortcuts kbd").first()).toContainText("⌘");
  await page.getByRole("radio", { name: "Windows / Linux" }).check();
  await expect(page.locator(".manual-shortcuts kbd").first()).toContainText("Ctrl");
  await page.screenshot({ path: `${directory}/shortcuts.png` });
  await hold();
  await page.locator('.manual-desktop-contents a[href="#house"]').click();
  await page.evaluate(() => document.documentElement.dataset.theme = "nightpress");
  await page.waitForTimeout(250);
  const theme = await page.locator('.toc-link').first().evaluate((element) => ({color: getComputedStyle(element).color, ink: getComputedStyle(element).getPropertyValue('--color-ink-light')}));
  expect(theme.color).toBe('rgb(196, 187, 171)');
  await page.screenshot({ path: `${directory}/nightpress.png` });
  await hold();
  await page.evaluate(() => document.documentElement.dataset.theme = "foolscap");
  await page.setViewportSize({ width: 390, height: 844 });
  await page.evaluate(() => window.scrollTo(0, 0));
  await expect(page.locator(".manual-mobile-contents")).not.toHaveAttribute("open", "");
  await expect(page.getByRole("heading", { name: "Begin a piece", exact: true })).toBeVisible();
  await noOverflow();
  await page.screenshot({ path: `${directory}/mobile.png` });
  await hold();
  await page.locator(".manual-mobile-contents summary").click();
  await page.locator('.manual-mobile-contents a[href="#house"]').click();
  await expect(page).toHaveURL(/#house$/);
  await expect(page.locator(".manual-inheritance")).toBeVisible();
  await noOverflow();
  await page.screenshot({ path: `${directory}/mobile-house.png` });
  await hold();
  await page.setViewportSize({ width: 320, height: 700 });
  await noOverflow();
  await page.locator("#shortcuts").scrollIntoViewIfNeeded();
  await expect(page.getByRole("radio", { name: "Windows / Linux" })).toBeChecked();
  await noOverflow();
  await page.setViewportSize({ width: 1440, height: 900 });
  await page.emulateMedia({ media: "print" });
  await expect(page.locator(".manual-contents")).toBeHidden();
  await expect(page.locator("#launch-film")).toBeHidden();
  await page.pdf({ path: `${directory}/manual-print.pdf`, format: "A4", printBackground: true });
  await page.emulateMedia({ media: "screen" });
  await page.evaluate(() => window.scrollTo(0, 0));
  await hold();
  expect(errors).toEqual([]);
  result = { passed: true, assertions: ["contents match ordered chapters", "keyboard skip link", "anchor navigation", "Mac and Windows/Linux shortcut labels", "collapsed mobile contents", "no overflow at 320/390/1440", "nightpress reading", "print hides navigation and film", "nightpress links use the live theme colour", "no page errors"], boundary: "Actual local manual UI in Chromium; no authenticated provider exchange. Reduced motion enabled. Vite's diagnostic badge hidden for product footage." };
} catch (error) {
  result = { passed: false, error: String(error), pageErrors: errors };
  process.exitCode = 1;
  await page.screenshot({ path: `${directory}/failure.png` });
} finally {
  const video = page.video();
  await context.close();
  result.video = await video.path();
  if (result.passed) await copyFile(result.video, `${directory}/../manual-walkthrough.webm`);
  await browser.close();
  await writeFile(`${directory}/result.json`, JSON.stringify(result, null, 2));
  console.log(JSON.stringify(result, null, 2));
}

