import { component$, useSignal, useVisibleTask$ } from "@qwik.dev/core";
import {
  statusColor,
  statusLabel,
  lastSavedLabel,
} from "./sync-indicator-helpers";
import type { SyncStatus } from "../../utils/convex-sync";
import { subscribeSyncStatus } from "../../utils/convex-sync";

/**
 * The tiny dot in the editor toolbar that shows whether the
 * local draft is in sync with the server. The status is
 * pushed by `convex-sync` via the `twyne:sync-status` event;
 * this component just renders it.
 */
export const SyncDot = component$(() => {
  const status = useSignal<SyncStatus>({ kind: "local-only" });

  // eslint-disable-next-line qwik/no-use-visible-task
  useVisibleTask$(({ cleanup }) => {
    const unsubscribe = subscribeSyncStatus((s) => {
      status.value = s;
    });
    cleanup(() => unsubscribe());
  });

  return (
    <span
      class="inline-block w-2 h-2 rounded-full"
      style={{
        backgroundColor: statusColor(status.value),
        boxShadow: "0 0 0 1px rgba(0,0,0,0.04)",
        transition: "background-color 200ms ease",
      }}
      aria-label={statusLabel(status.value)}
      title={statusLabel(status.value)}
    />
  );
});

/**
 * The "Saved Xs ago" line that lives in the editor colophon.
 * The Lix mirror (separate from Convex) writes the manuscript
 * to the local Lix store on a 1.2s debounce; this label ticks
 * to the most recent successful mirror. Until the first mirror
 * fires, the line reads "Not saved yet" so the writer always
 * knows where the cursor is.
 */
export const LastSavedLine = component$<{ savedAt: number | null }>(
  ({ savedAt }) => {
    // Re-evaluate the label every second so the age stays
    // current. The interval is a 1Hz tick — cheap, and the
    // label is short enough that the DOM diff is trivial.
    const label = useSignal(lastSavedLabel(savedAt));
    // eslint-disable-next-line qwik/no-use-visible-task
    useVisibleTask$(({ cleanup, track }) => {
      track(() => savedAt);
      label.value = lastSavedLabel(savedAt);
      const tick = setInterval(() => {
        label.value = lastSavedLabel(savedAt);
      }, 1000);
      cleanup(() => clearInterval(tick));
    });
    return <span>{label.value}</span>;
  },
);
import {
  loadMetaFromIdb,
  saveMetaToIdb,
  loadFolioContentSnapshotFromIdb,
} from "./idb";

export interface RevisionSnapshot {
  id: string;
  folioId: string;
  html: string;
  typstSource?: string;
  createdAt: number;
  label: string;
  source: "automatic" | "manual" | "feedback" | "rubric";
  wordCount: number;
}

export interface RevisionComparison {
  wordsBefore: number;
  wordsAfter: number;
  wordsChanged: number;
  paragraphsBefore: number;
  paragraphsAfter: number;
}

export interface RevisionPassageChange {
  before: string | null;
  after: string | null;
}

export interface RevisionTask {
  id: string;
  folioId: string;
  title: string;
  detail?: string;
  sourceId?: string;
  source: "feedback" | "suggestion" | "manual";
  status: "open" | "done";
  createdAt: number;
  completedAt?: number;
}

const MAX_REVISIONS = 50;
const AUTO_INTERVAL_MS = 5 * 60_000;
let storage = { load: loadMetaFromIdb, save: saveMetaToIdb };

/** Test seam that avoids process-wide module mocks leaking into other suites. */
export function __setRevisionStorageForTests(
  adapter: typeof storage | null,
): void {
  storage = adapter ?? { load: loadMetaFromIdb, save: saveMetaToIdb };
}

function historyKey(folioId: string): string {
  return `revision-history:${folioId}`;
}

function tasksKey(folioId: string): string {
  return `revision-tasks:${folioId}`;
}

function plainText(html: string): string {
  return html
    .replace(/<[^>]*>/g, " ")
    .replace(/&nbsp;/g, " ")
    .replace(/&amp;/g, "&")
    .replace(/\s+/g, " ")
    .trim();
}

function words(html: string): string[] {
  const text = plainText(html);
  return text
    ? text
        .toLocaleLowerCase()
        .split(/\s+/)
        .map((word) => word.replace(/^\W+|\W+$/g, ""))
        .filter(Boolean)
    : [];
}

function paragraphs(html: string): number {
  return (html.match(/<(?:p|h[1-6]|li|blockquote)\b/gi) ?? []).length;
}

function decodeEntities(value: string): string {
  const named: Record<string, string> = {
    amp: "&",
    apos: "'",
    gt: ">",
    lt: "<",
    nbsp: " ",
    quot: '"',
  };
  return value.replace(
    /&(#x[\da-f]+|#\d+|[a-z]+);/gi,
    (entity, code: string) => {
      if (code[0] !== "#") return named[code.toLowerCase()] ?? entity;
      const numeric =
        code[1]?.toLowerCase() === "x"
          ? Number.parseInt(code.slice(2), 16)
          : Number.parseInt(code.slice(1), 10);
      return Number.isInteger(numeric) && numeric >= 0 && numeric <= 0x10ffff
        ? String.fromCodePoint(numeric)
        : entity;
    },
  );
}

function passageText(html: string): string[] {
  return decodeEntities(
    html
      .replace(/<br\s*\/?>/gi, "\n")
      .replace(/<\/(?:p|h[1-6]|li|blockquote|pre|div)>/gi, "\n")
      .replace(/<[^>]*>/g, " "),
  )
    .split(/\n+/)
    .map((passage) => passage.replace(/\s+/g, " ").trim())
    .filter(Boolean);
}

function findNearby(
  passages: string[],
  target: string,
  from: number,
  distance: number,
): number {
  const end = Math.min(passages.length, from + distance + 1);
  for (let index = from + 1; index < end; index += 1) {
    if (passages[index] === target) return index;
  }
  return -1;
}

export async function loadRevisionHistory(
  folioId: string,
): Promise<RevisionSnapshot[]> {
  const history = await storage.load<RevisionSnapshot[]>(historyKey(folioId));
  if (!Array.isArray(history)) return [];
  return history
    .filter(
      (entry) =>
        entry &&
        entry.folioId === folioId &&
        typeof entry.html === "string" &&
        typeof entry.createdAt === "number",
    )
    .sort((a, b) => b.createdAt - a.createdAt)
    .slice(0, MAX_REVISIONS);
}

export async function createRevisionSnapshot(args: {
  folioId: string;
  html: string;
  typstSource?: string;
  label?: string;
  source?: RevisionSnapshot["source"];
  now?: number;
  force?: boolean;
}): Promise<RevisionSnapshot | null> {
  if (!args.folioId) return null;
  const now = args.now ?? Date.now();
  const source = args.source ?? "manual";
  const history = await loadRevisionHistory(args.folioId);
  const latest = history[0];
  const current =
    args.typstSource === undefined
      ? await loadFolioContentSnapshotFromIdb(args.folioId)
      : null;
  const typstSource =
    args.typstSource ??
    (current?.html === args.html ? current.typstSource : undefined);
  if (
    latest?.html === args.html &&
    latest?.typstSource === typstSource &&
    !args.force
  )
    return null;
  if (
    source === "automatic" &&
    !args.force &&
    latest &&
    now - latest.createdAt < AUTO_INTERVAL_MS
  ) {
    return null;
  }
